import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:bodytmi/bodytmi.dart';
import 'package:bodytmi_core/bodytmi_core.dart';
import 'package:sqlite3/sqlite3.dart';

Future<void> main(List<String> arguments) async {
  try {
    if (arguments.isEmpty ||
        (arguments.length == 1 && arguments.single == '--help')) {
      stdout.writeln(
        jsonEncode({
          'schemaVersion': 1,
          'commands': [...commandNames, ...storedCommandNames],
          'usage': 'bodytmi <group> <action> [--input FILE|-]',
          'input': 'One JSON request, schemaVersion: 1, from stdin or --input.',
          'storage':
              'store commands require a database path in the JSON request. Existing commands use explicit snapshots.',
          'backup':
              'create requires database/destination; validate requires source; restore requires database/source/recoveryDestination/confirm:true. Backup paths are directories.',
          'archive':
              'export requires database/destination; validate requires source; restore requires database/source/recoveryDestination/confirm:true. Logical exports are JSON files; recovery backups are directories.',
          'skipRemaining':
              'store skip-remaining takes database/id/expectedVersion/confirm:true and skips all planned efforts without changing completed results or finishing the session. Stop and review or discard session clocks first; use execution skip-group during traversal. session skip-remaining takes session/confirm:true and requires the caller to account for external clock/traversal state.',
          'skipSlot':
              'store skip-slot takes database/id/expectedVersion/slotId/confirm:true and optional role (work, warmup, backoff or drop); session skip-slot takes session/slotId/confirm:true and optional role. The same clock and traversal safeguards apply.',
          'editTarget':
              'store save-back takes database/id/mode and confirm:true when publishing (policy bodytmi-save-back/1, the Q35 choices): mode session keeps every edit session-only and only reports the diff; save publishes one revision when the session\'s explicit target edits change the prescription; increment always publishes a visible revision boundary. Edited targets become per-effort targets on their authored effort (every occurrence of a repeated effort must agree); actual results are never copied, and progression-controlled metrics, program overrides, substituted sets and metrics without an authored slot target stay session-only (listed in notSaved with a reason). If the template head moved past the session revision, save-back conflicts unless newTemplateId saves a separate template. The session keeps its pinned revision. session edit-target takes session/setId/metric/value and optional applyToRemaining; store edit-target takes database/id/expectedVersion/setId/metric/value and optional applyToRemaining. Edits planned suggestions only; explicit carry skips authored, derived and manually edited targets. Stored edits cannot change sets with active or unreviewed effort clocks.',
          'carryActual':
              'session carry-actual takes session/setId/metric; store carry-actual takes database/id/expectedVersion/setId/metric. Copies one completed actual to later compatible untouched suggestions in the same slot and role, with the same safeguards as edit-target.',
          'progression':
              'propose requires database/sessionId/slotId/rule; accept requires database/sessionId/slotId/expectedVersion/acceptedAt; decline requires database/sessionId/slotId/expectedVersion/declinedAt; show requires database/sessionId/slotId. Declines hold targets and resolve exposure counters once. Stored application supports manual double, numeric threshold and ordinal level progression; propose accepts optional ruleType:threshold (all/roundRobin/weighted/chosen/priority coordination) or ruleType:ordinal with the corresponding rule. Chosen requires coordination.metric; priority requires a unique order and selects one candidate applicable across the complete target vector, with blocked-set explanations. Chosen/priority retain a zero cursor. Threshold performance:{direction:higher/lower,failureLimit,advancementLimit} replaces legacy minimum/threshold when supplied and is independent of lever directions. Best follows performance direction. Threshold rule aggregation supports all/any/best/last/total/kOfN (count required); failureAggregation supports all (default) or total. Threshold directions map controlled metrics to increase (default) or decrease; increments remain positive step sizes, minimums/maximums are inclusive lever bounds, and configured deloads move in the easier direction. Missing work stays unknown and failure gates advancement. Only accepted applicable transitions consume coordinator positions. reconcile-status takes database/templateId/revision/slotId/asOf and optional role, runId, sessionId, rule and ruleType; it reports the accepted track, the candidate prescription/session views and every named difference (workingSetCount, slotTarget, metricDimension, effortTarget, objectiveCriteria, sessionTarget, rule) that makes a later store start or progression propose need explicit reconciliation. Conflicts now name these kinds too. Reporting writes nothing and reconciles nothing. reconcile takes database/id/templateId/revision/slotId/expectedSequence/kinds/reconciledAt/confirm:true and optional role, runId, sessionId, rule, ruleType, resetFailures and resetCursor; it records one durable receipt that supersedes the resolved track anchor, adopts only the planned suggestions of the candidate prescription or session, carries failure counters and coordinator positions unless explicitly reset, and requires kinds to equal the current blocker kinds; expectedSequence is compare-and-set and one identity records one act. reconcile-show takes database/id; reconcile-list takes database. A receipt re-anchors later store starts, plan refreshes and proposals without replaying prior terminal decisions, counters or program advancement. Threshold rules may declare retest:{metric,repetitions:{metric,minimum},factor,roundTo?,stage?,restartStage?}: where the rule would deload (staged tiers: on exhausting the last stage) the outcome is retest (targets held, failures reset; nextStage plans the optional test stage, whose authored variant branch replaces the lift in the next session). progression retest takes database/id/templateId/revision/slotId/sourceSessionId/sourceSetId/expectedSequence/reseededAt/confirm:true and optional role/runId: the named set (any finalized session, same exercise/implementation/equipment, completed, uninterrupted, at least the minimum repetitions) reseeds the metric at factor × its actual (floored to roundTo) at the restart stage with failures and cursor reset, as a receipt with retest provenance. Nothing counts unless named; progression track reports retestPending. Propose rejects a session that planned the test stage.',
          'observations':
              'session annotate takes session/setId/observations; store annotate takes database/id/expectedVersion/setId/observations. Replaces optional rpe:{value:decimal string,scale:0-10 or 6-20}, rir:nonnegative decimal string, notes (up to 4000 characters), terminationReason:target-reached/max-effort/grip-failure/pain-discomfort/interrupted/other. RPE/RIR require completed actuals. Empty observations clears with confirm:true. Interrupted sets remain in raw reports but are excluded from prefill, stored progression and records. Other reasons are descriptive. Stop the associated active effort clock before annotating.',
          'effortConditions':
              'Threshold rules optionally declare advancementEffort:{rpe:{scale:0-10/6-20,minimum?,maximum?},rir:{minimum?,maximum?}} with decimal-string inclusive bounds. All configured ratings on all required results must qualify. Only advancement is gated: numeric failures/deloads retain precedence; a known unmet gate holds and resets failures, while missing/mismatched ratings at the advancement boundary yield unknown and preserve failures. RPE scales never convert; pain notes remain descriptive. Pure progression evaluate accepts an aligned observations array; stored threshold proposals use the frozen set observations. Interrupted observations make results unknown. Rule changes require reconciliation.',
          'ordinalProgression':
              'ruleType:ordinal rules move the controlled target vector between explicitly authored levels. Rule shape: metric (performance metric), performance:{direction:higher/lower,failureLimit,advancementLimit} (required, inclusive), levels:[{id,targets}] ordered easiest to hardest (1-1000 levels, identical controlled metric keys and dimensions, distinct vectors), optional aggregation/failureAggregation (same modes as threshold rules), optional advancementEffort (same effort gate), optional deloadAfter and deloadLevel (an explicit easier level id). Levels carry complete working targets; harder direction is authored order, never inferred from numbers. Evaluation locates the current level by exact canonical match of every set suggestion; anything else yields review with no counter change. Outcomes: unknown, failed, deload, hold, advance, blocked at the hardest level or at an unreachable deloadLevel. Advance/deload move every working set to one level atomically; there is no coordinator position. Pure command progression ordinal takes rule/currentSets/results/state/optional observations. Later store starts consume accepted level targets. Ordinal levers cannot back shared lever links.',
          'derivedTargets':
              'target resolve evaluates an explicit acyclic graph of source, scale, add, subtract and round nodes. Sources declare unit, sourceId, sourceVersion and value (null when missing); scales declare unit, input and decimal-string factor; add/subtract declare unit, left and right dependencies; round declares input, native scale and rounding policy. Results retain source provenance, use exact canonical arithmetic, propagate missing inputs, and reject negative subtraction.',
          'derivedTargetSnapshots':
              'target capture takes an authored graph and explicit bindings keyed by sourceId, each with version and value. Missing bindings remain unresolved. target status takes a captured snapshot and current bindings, verifies the snapshot and reports source changes and both resolutions. These pure commands do not publish, persist or refresh workout sessions.',
          'derivedTargetGraphs':
              'graph validate takes a reusable graph with source/scale nodes and per-source binding policies: manual (version + value), bodyMass (context, optional asOf and resolver options) or history (metric, direction highest/lowest, optional template/slot/exercise/implementation/equipment/setup/role/ordinal scope, inclusive from, exclusive until, includeWarmups). graph publish requires database/graph/expectedRevision; show takes database/graphId and optional revision; list returns all revisions. graph resolve takes database/graphId, optional revision and asOf, and optional runId or allRuns:true. History defaults to ad hoc sessions; runId selects one run, allRuns explicitly combines all contexts. asOf excludes history finalized after the cutoff and constrains body mass. Body-mass and history provenance include source fingerprints; their sourceVersion values describe only the maximum individual measurement version or selected session version, not a series version. Resolution returns per-source provenance plus the exact resolution. Resolving never modifies graphs, sessions or progression; unresolved sources propagate without inventing values.',
          'graphPreview':
              'graph preview takes database/templateId/revision/graphId/graphRevision/asOf/bindings and optional runId. Each binding maps occurrenceId/metric/nodeId. It previews explicit graph-derived targets without publishing, starting or changing a session. Unresolved values remain unknown; ordinary history prefill and accepted progression are not applied.',
          'graphWorkoutPlans':
              'Published graphs may include plans with id/templateId/revision/bindings; each binding selects occurrenceId/metric/nodeId. Publishing validates the pinned workout and units. graph plan-preview takes database/graphId/graphRevision/planId/asOf and optional runId to preview a saved plan. Plans can also be selected at session start.',
          'derivedSessionPlans':
              'store start and run start optionally accept derivedPlan:{graphId,graphRevision,planId}. Published plans with manual, body-mass or history graph sources and numeric targets or bounded objectives are frozen and applied at start. History is scoped to the selected run or ad hoc context, and requires earlier finalized sessions. Overlap with accepted progression is rejected; observe and max-effort objectives cannot receive suggestions. Retry must use the same plan reference.',
          'derivedSessionPlanStatus':
              'store plan-status takes database/id and compares the stored session’s frozen plan and source evidence with current inputs at its original start cutoff and run scope. Sessions without a derived plan report configured:false. History must have started before the session and finished by its start time. It is read-only and does not change session suggestions or progression. store plan-refresh takes database/id/expectedVersion/expectedPreview/confirm:true, where expectedPreview is comparison.currentPreview from store plan-status. It verifies that preview atomically and re-resolves the same pinned plan before work, timing or traversal; it does not change slot body-mass inputs.',
          'graphPlanStatus':
              'graph plan-status takes database/planPreview from graph plan-preview. It verifies that the mapping is the published plan and reports source and target changes in its original scope. Captured source evidence is caller-provided and not authenticated; no session is started or modified.',
          'graphPreviewStatus':
              'graph preview-status takes database/preview from graph preview and compares its pinned workout, graph, source fingerprints and mapped values with current data in the same scope. Caller-supplied preview evidence is not authenticated; this read-only query does not authorize or start a session.',
          'graphStatus':
              'graph status takes database/snapshot from graph resolve, checks graph revision, scope and arithmetic, then compares the captured sources with a fresh resolution in the same scope. The supplied snapshot is caller-provided evidence, not an authenticated audit record; status never changes a session or progression.',
          'publishedObjectives':
              'Effort objectives may declare exact, minimum, maximum, range, observe or maxEffort criteria using the objective evaluate schema. Maximum/range require an explicit upperMeaning. Bounds are descriptive, not prohibited actuals or automatic progression rules. Numeric suggestions remain independently accepted; observe/maxEffort require explicitly entered actuals. Targetless objectives require an explicit actual. Pinned criteria appear in session summaries/series, and changed working objectives require progression reconciliation.',
          'objectiveAssessment':
              'objective evaluate takes objectives and actuals; session assess-objectives takes session/setId/objectives; store assess-objectives takes database/id/setId/objectives. Criteria are explicitly supplied for this read-only query, not saved to the workout. Modes: exact(value), minimum(minimum), maximum(maximum,upperMeaning), range(minimum,maximum,upperMeaning), observe(unit), maxEffort(unit:rep). upperMeaning is desiredCeiling/progressionThreshold/stoppingCue. Bounds are inclusive, missing values stay unknown, and the report never applies progression or delivers cues.',
          'objectives':
              'Effort activities may declare objectives:{metric:{mode:maxEffort,unit:rep}}. Each declared repetition metric is explicitly observed without a numeric suggestion; acceptSuggested cannot supply it. Completion, execution and timer confirmation require its actual count, including an explicit zero. Threshold progression can use these actuals without inventing targets. Changing working objective modes requires progression reconciliation. Time-window AMRAP remains pending.',
          'effortTargets':
              'Effort activities may declare nonempty targets overrides for existing slot metrics with compatible dimensions. Other metrics inherit slot targets; repeat occurrences retain independent results. Authored overrides take precedence over history prefill for those metrics. Published slot timing defaults must resolve for each authored override. Accepted progression can supply controlled working targets when the authored baseline is unchanged; changed controlled per-effort targets require reconciliation. Warmups stay independent.',
          'incrementBands':
              'Threshold rules optionally declare incrementBands:{aggregation:{mode:last/best/total},bands:[{id,threshold, increments}]}. Thresholds use the performance metric/direction and must be strictly ordered from easier to harder; strongest qualifying inclusive band replaces every base increment with compatible positive steps. Otherwise base steps apply. Numeric/effort gates precede selection; bounds hold the whole vector without falling back to a lesser band. Existing coordinator selection, native scale rounding and resets remain explicit. Proposals expose incrementBandAssessment. This is generic performance-dependent stepping, including last-set bonus steps.',
          'scales':
              'scale validate takes scale{id,unit} with exactly one of ticks:[{id,value,labels?}] or range:{start,step,count,idPrefix?}. Fixed ranges declare 1–1000 native positions with a positive step and deterministic tick IDs. scale resolve also takes target/rounding (nearest/atMost/atLeast), with optional beyond/direction together. Threshold scales bind controlled metrics to frozen scale/rounding/deloadRounding; directional lookup excludes the current setting and records selected ticks. These are nominal numeric settings; inventories and plate arrangements remain separate.',
          'bodyMass':
              'mass record/update/delete/show/list/trend/resolve use stored observations and require database. Measurements may include optional source and notes; updates replace the observation and require expectedVersion. Deletion requires expectedVersion and confirm:true. measurement trend/resolve still take explicit measurement arrays.',
          'sessionBodyMass':
              'Slots may explicitly configure bodyMass.context and resolver options. Session starts freeze selected inputs; optional bodyMassOverrides maps slot IDs to measurementId or mass overrides. store mass-status takes database/id; session mass-status takes session/measurements. Source changes do not rewrite captured inputs. store mass-refresh requires database/id/expectedVersion/confirm:true and explicitly recaptures slot mass at the original start cutoff before work, timing or traversal; session mass-refresh accepts session/measurements/confirm:true. Existing overrides and derived plans stay pinned. store mass-rebind takes database/id/expectedVersion/bodyMassOverrides/confirm:true to replace selected slot overrides before work; a null slot override returns to its configured trend. Original start identity and derived plans remain pinned.',
          'effectiveLoad':
              'Slots may configure an effectiveMass model with explicit bodyMassFraction, addedMass and assistance components. store effective-load takes database/id; session effective-load takes session. Derived suggested/confirmed-actual estimates preserve raw inputs and do not change progression.',
          'programs':
              'program publish pins workout revisions and may pin a derivedPlan per day; run create takes id/programId/revision/startedAt and a required loop (true repeats the program, false ends the run after its last day) and permits multiple active runs. Pinned day plans are applied automatically at run start. run start selects runId; store finish advances its bound occurrence once. Use run show/list for cursor and currentSessionId; run schedule takes runId and optional count (1–1000) and includeScopes to inspect upcoming days and authored group/repeat context without dates or changes. run upgrade takes runId/expectedVersion/revision/requestId/at/confirm:true and explicitly re-pins the run to another published revision of the same program without moving its cursor; the receipt records the cursor so completed days stay bound to the revision they ran under (a looping run may change any day, including ones already done), the cycle length cannot change once the run has advanced, the current day needs no session yet, and finite runs need enough days. run upgrades lists the durable receipts. Day/group/repeat nodes may declare overrides:[{slotId,metric,mode:scale|set,factor|quantity}]; ancestor overrides apply to their days and the nearest declaration wins per slot metric, replacing authored targets exactly before history prefill. Overrides never silently replace an accepted progression-controlled metric; reconcile the track first, and sessions freeze the applied before/after provenance.',
          'analytics':
              'session summary takes session; store summary takes database/id. Optional sumMetrics explicitly selects raw metric sums; warmups are excluded by default. history series/records take sessions and optional runBySession; store series/records read database history. Summaries, series and records support explicit roles selection; series also support metric, exact context, inclusive from/exclusive until and includeActive. Only confirmed results appear; series retain separate role/slot/setup/equipment/run contexts and source versions.',
          'records':
              'history records takes sessions/metric/direction (higher/lower); store records takes database/metric/direction. Optional atActuals filters exact observed quantities; context/from/until/includeWarmups and family selection mirror series (records always use finalized work). Other observed metrics, setup/run/role and timing guidance stay separate. Tracked body-mass/derived-load contexts are excluded pending record policies. Reports include neutral markers, ties, source versions and exclusions; queries do not apply progression. store records includeImported:true (+importNamespace) adds a separate imported section (bodytmi-imported-records/1): completed imported sets only, exact imported contexts with other actuals held fixed, never merged with native records; run/template/slot/setup filters exclude it. includeBlocks:true (+amrapId) adds blocks (bodytmi-block-records/1): confirmed-round scores of finalized AMRAP blocks that ran to their deadline, compared within one run/template/block/frozen loop; partial rounds are reported, not scored.',
          'repeatHistory':
              'repeat-checkpoint series takes database and optional sessionId, runId, metric, from, until, includeWarmups and includeActive. history repeat-series takes checkpoints, sessions and optional runBySession with the same filters. Results retain their repeat definition and session/run context; dates filter session start, and occurrence times are unrecorded. repeat-checkpoint rounds and history repeat-rounds use the same inputs except metric/includeWarmups and include empty attempts plus explicitly reviewed round counts; after-boundary flags record review submission only.',
          'families':
              'family validate takes family{id,name,exercises}. family publish requires database/family/expectedRevision; show takes database/familyId and optional revision; list returns all revisions. Families may overlap and do not imply comparable loads. store series accepts familyId and optional familyRevision; history series accepts a family revision snapshot. Reports pin membership and preserve contextual series.',
          'catalog':
              'Exercises, implementations and equipment accept optional labels{<language tag>:{name?,aliases?}} (canonical tags such as sv or sv-SE, 1–64 locales, up to 32 aliases each); the root name stays the locale-neutral fallback and labels never change identity. catalog search takes database/query and optional locale/kinds(exercise|implementation|equipment)/limit(1–1000, default 50); policy bodytmi-catalog-search/1 searches the latest revisions case-insensitively without accent folding, ranks exact/prefix/word-prefix/substring matches of id, root name, label names and aliases (with locale: only its exact and language-only labels), and returns displayName resolved exact, language, then root. exercise publish requires database/exercise/expectedRevision and stores immutable numbered revisions of exercise{id,name?,notes?,labels?}; show takes database/exerciseId and optional revision; list returns all revisions. implementation publish requires database/implementation/expectedRevision for implementation{id,exerciseId,name?,notes?}; the referenced exercise must already be published, and exerciseId is immutable across revisions; show takes database/implementationId and optional revision; list returns all revisions. Catalog adoption: a slot implementation identifier that matches a published implementation must belong to that slot exercise, and stored publication, archives and backups enforce this; unmatched identifiers stay legacy authoring shorthand. Optional requireCatalog:true on store publish demands every slot exercise and slot implementation-of-that-exercise be published catalog identities and every declared slot equipment a published equipment definition, and on family publish demands every member be a published exercise; missing identities report not_found. Catalog entries never prescribe targets, progression, timing or records, and nothing keys behaviour off an exercise name.',
          'equipment':
              'equipment publish requires database/equipment/expectedRevision for equipment{id,name?,notes?}; gym publish takes gym{id,name?,notes?}; both store immutable numbered revisions and compare-and-set on the per-id head. instance publish takes instance{id,equipmentId,gym?,name?,notes?,scale?,loading?}; the equipment kind and gym must already be published, and equipmentId is immutable across revisions while a gym move, scale or loading change is a new revision. An optional inline scale declares the instance native markings with alternate same-dimension printed labels only; it is display provenance, never an independent load or plate math. An optional loading{components,channel,plates} declares one plate-loading configuration: tare components (bar/collar/handle/tare with explicit include), exactly one channel (one or two sides with required or independent symmetry), and the actual plate denominations and counts at this instance. plate plan takes loading and a mass target and returns only feasible arrangements: exact, or explicitly labeled nearest-lower and nearest-higher choices, never a silent rounding. store plate-plan takes database/instanceId/optional revision/target and evaluates the stored instance configuration; instances without a loading declaration have no plate arithmetic and nothing assumes a bar mass, collars or symmetric sides. Symmetric channels consume plate pairs; independent channels allocate sides as display-only. instance show takes database/instanceId and optional revision; instance list returns all revisions; instance inventory takes database and optional gymId and returns the latest revision of each instance, which is its effective placement. Inventory entries never prescribe targets, progression or records, and slot equipment adoption is pending. An optional instance convention{massBasis,implements?,sides?,repCounting?,notes?} declares how entered mass and repetitions are interpreted: per-implement (mass per implement, 1-64 implements), per-side, assembly-total, added-load or nominal-setting; sides both/left/right and repCounting per-side/combined keep unilateral counting separate. A per-side basis requires a declared symmetric two-sided loading channel and added-load requires declared components; no imaginary bar is ever assumed. Slots may declare the same convention to override the instance default. convention validate takes convention; convention interpret takes convention/mass/optional repetitions/loading and returns exact labeled per-implement, assembly and added masses with explicit unknown reasons plus repetition side expansion, never rewriting entered values or computing totals. store load-convention takes database/instanceId/optional instanceRevision, optional templateId/templateRevision/slotId, optional convention/mass/repetitions and resolves explicitly first, then the slot override, then the instance default, with capability evidence.',
          'sessionLoadContext':
              'Session starts freeze which equipment instance and load entry convention each slot used. store start and run start take optional loadBindings:{slotId:instanceId} (resolved to the latest published instance revision) and loadConventions:{slotId:convention} session overrides; pure session start takes loadInstances with full instance snapshots. Precedence is the session override, then the pinned slot convention, then the instance default, captured once at start; later instance revisions, gym or loading moves never rewrite the session. A bound instance must match the slot declared equipment. Edited, carried or manual targets, results and progression are unaffected. store load-status takes database/id; session load-status takes session/optional instances and reports source or target changes without rewriting the session.',
          'loadArrangements':
              'store arrange takes database/id/expectedVersion/setId/optional arrangement/confirm; session arrange takes session/setId/optional arrangement/confirm. An arrangement {instanceId,channel,plates:[{mass,count}]} records the exact plate stack one completed set used on the session frozen instance revision; counts are totals across the channel and every denomination must be declared stock, split equally on a symmetric channel. Masses are always recomputed exactly from the frozen loading declaration; nothing assumes a bar or tare. An arrangement requires the slot frozen instance binding. Clearing needs arrangement:null with confirm:true. Skipped sets discard arrangements. store arrange-status takes database/id; session arrange-status takes session/optional instances keyed by slot. They report each recorded stack against the current instance head: computed channel and total mass, deterministic side display split, feasibility under current stock, whether a fresh plate plan would choose that stack, convention drift and the descriptive entered-mass relation. Reports never rewrite a recorded stack or its entered mass.',
          'performedOn':
              'store perform-on takes database/id/expectedVersion/setId/instanceId (null clears, with confirm:true) and optional applyToRemaining to record that a set, and the later untouched sets of its slot and role, are performed on another published instance of the slot equipment, e.g. the kg machine when the lb one is taken. The latest instance revision is frozen on the set; targets keep their own unit. The response lists, per set and metric, the nearest settings on that instance to each target (both neighbours on an exact tie). Progression counts a controlled actual equal to such a nearest setting on the instance used (the set\'s performedOn, else the session binding) as following the target, reports it as followedSettings, and keeps progressing in the track\'s unit; an available target must still be met exactly. A plate arrangement on such a set belongs to its performedOn instance.',
          'locale':
              'Presentation only (policy bodytmi-locale/1); canonical records and all other JSON stay locale independent, and a locale never implies a unit preference. Every locale command takes locale (BCP 47, e.g. sv-SE), resolved exactly, then by language, then the en root, reported as match exact/language/root. locale info returns decimal/group separators, minus sign, zero digit, grouping sizes, ISO firstWeekday (1 Monday ... 7 Sunday), weekendDays, hourCycle and message catalog. locale format-number takes a decimal string value and optional grouping (default true) and minimumFractionDigits (zero padding only; digits are never rounded). locale parse-number takes text and optional allowGrouping: locale or ASCII digits, the locale minus sign or -, exactly the locale decimal separator, and group separators only when allowed and at locale grouping positions; it returns a canonical decimal string. locale format-date takes value (timestamp with offset, or YYYY-MM-DD for style date), style date/time/datetime and hourCycle locale/h12/h24, formatting the recorded wall clock, never the process timezone. locale format-duration takes whole milliseconds and style clock (m:ss or h:mm:ss) or units; locale parse-duration accepts only m:ss, h:mm:ss or explicit descending units (h, min/m, s with optional fraction, ms) and rejects bare numbers, returning milliseconds plus a seconds quantity. locale message takes a stable key and args (count for plural keys) and reports the catalog used and any fallback to en.',
          'historyImport':
              'import validate takes document in format bodytmi-history-import/1: source{namespace,app?,version?,exportedAt?}, sessions[{sourceId,date (YYYY-MM-DD) xor startedAt (timestamp with offset),finishedAt?,timezone?,name?,notes?,raw?,exercises[{sourceId,order,name,exerciseId?,implementationId?,equipment?,convention?,notes?,raw?,sets[{sourceId,ordinal,role work/warmup/backoff/drop/unknown,status completed/skipped/interrupted/unknown,actuals?,targets?,observations?,raw?}]}]}] and measurements[{id,sourceId,context,observedAt,mass,notes?}]. Every quantity names its unit; raw preserves unresolved source fields (integers or strings only). import preview takes database/document and reports new/unchanged/changed/conflict per record plus absent records, without writing. import apply additionally takes importedAt, confirm:true and optional onChanged reject (default) or update; it writes the whole plan in one transaction or nothing, reuses source identities so identical reimports are no-ops, and never deletes records absent from a later export. Imported measurements become body-mass observations in their explicit context with source provenance; another source or deleted identity conflicts. Imported sessions pin no workout revision and never feed prefill, progression, records or program cursors. import list takes database and optional namespace; import show takes database/namespace/sourceId; import delete takes database/namespace/sourceId/expectedVersion/confirm:true. import series takes database/metric and optional namespace, exerciseId, exerciseName, roles (default all but warmup), from inclusive and until exclusive calendar dates; contexts keep namespace, catalog mapping or exact source name, implementation, equipment, convention, role and entered unit separate, and date-only sessions are never given an invented time. store series optionally takes includeImported:true and importNamespace to add a separate imported block (policy bodytmi-imported-series/2) that never merges into native contexts: context runId/templateId/slotId/setupNote filters exclude imported history entirely, exercise/implementation/equipment/role match exactly, instant from/until exclude and count date-only sessions, family membership uses mapped exerciseId only, unknown roles appear by default but explicit roles must be native roles, and the 10000-point budget is shared. To map an exercise after import, re-import it with exerciseId set and onChanged:update.',
          'links':
              'link create requires database/link/expectedRevision/createdAt/confirm:true. A link names id, optional name, distinct shared metrics, optional cadence each-exposure (default) or manual, exactly 2–32 member resolved progression track IDs and a baseline member ID. Members must share the rule kind and coordinated lever shape, the same working-set count, and every shared metric must be controlled at one dimension in every member vector; one track backs at most one link. Membership and baseline are immutable per link identity; later revisions change only name, metrics or cadence, and expectedRevision is compare-and-set. link show takes database/linkId and optional revision; link list returns all revisions; link status evaluates a candidate link against current stored tracks without writing. Consumption is durable: linked sessions resolve shared-metric targets from the link application chain at their start, terminal accept/decline of an each-exposure member appends one shared chain row with compare-and-set against the frozen start state, and manual links advance only via link advance (database/linkId/nextSets/failedSessions/optional cursor/expectedSequence/at/confirm:true). link state takes database/linkId and optional asOf and shows the chain and resolved shared state. link retire requires database/linkId/memberAnchorId/retiredAt/confirm:true and forks one member back to independent local targets; a member retired from one link may later join another. Links never advance programs and terminal receipts never replay.',
          'timing':
              'timer start creates a paused per-set clock; omitted metric selects the published timing metric or the only duration target, and omitted plan resolves the pinned slot timing defaults against its duration suggestion; timer rest times an authored rest occurrence. timer run uses a foreground monotonic clock. Optional stream:true emits NDJSON cue envelopes before the final response. Ctrl-C pauses; unexpected interruption requires explicit timer recover (freeze/adjust). Effort expiry never logs actuals: timer confirm requires expectedSessionVersion and explicit result review. Slots may publish timing defaults with an explicit duration metric, preparation, tempo, near-end and overrun. Explicit clock plans replace defaults. Optional plan.tempo defines repeating effort cues; tempoState exposes logical phase without counting achieved reps. Audio is pending.',
          'execution':
              'execution start/show/list/time/complete/confirm/advance/skip/skip-group/run traverse finite effort/rest occurrences. Timed rests prepare a clock; rest nodes with manual:true have no timer and require execution advance. run advances timed rest boundaries; timed efforts require explicit review. Actions require execution/session versions and stable requestId; corrections never replay cursor advancement. skip-group requires an explicit groupPath from the current groups list and confirm:true; it preserves existing results. Sets may be logged ahead of the cursor with store complete (e.g. while a station is busy); when the cursor reaches one, acknowledge it with execution advance. complete/confirm/skip/time on an already logged set conflict rather than overwrite it. Scoped windows are not yet supported.',
          'effortRoles':
              'Effort roles are work, warmup, backoff and drop. Prefill and reports keep roles separate; summaries include all except warmups by default and accept an explicit roles list. Graph history sources can explicitly filter by role. Stored progression propose/show/accept/decline accept an optional role, default work; each role has an independent receipt, targets and counter within its run.',
          'activityGroups':
              'activity groups takes definition and optional containing occurrence index. It reports half-open group bounds and authored durations for window scopes, including repeated and nested windows. This is structural inspection only; scoped window execution remains unsupported.',
          'blockProgression':
              'Durable AMRAP block progression (policy bodytmi-block-progression/1): the explicitly confirmed round score of a finished block drives one round slot targets. progression block-propose takes database/sessionId/amrapId/roundSlotId/rule for a finished session whose block checkpoint exists; rule is {performance:{score:confirmedRounds,failureLimit,advancementLimit},increments:{metric:quantity},maximums?,deloadAfter?,deloadDecrements?} and moves only slot-level targets of that round slot. Outcomes: advance (increments), hold (counter reset), failed (one failed exposure), deload (after deloadAfter failures), blocked (maximum or below zero; holds), unknown (block stopped or limited early: neutral) and review (a reviewed effort changed a controlled target). block-show takes the same identity; block-accept/block-decline add expectedVersion and acceptedAt/declinedAt and make an immutable receipt (unknown/review can only be declined; decline holds targets and resolves the counter once). The next repeat-checkpoint start-block for the same run, template, block and round slot starts from the latest decision resolved by the session start and records it in blockTargets. A changed source block makes a pending proposal stale; a newer resolution on the track conflicts. progression block-track takes templateId/amrapId/roundSlotId/optional runId/asOf. store series includeBlocks:true adds a separate blocks section of block results.',
          'phases':
              'Phases are labelled program groups (e.g. accumulation, deload, taper) with optional scoped overrides; no calendar is required. run schedule includeScopes:true lists each day\'s labels. Sessions started inside an overriding phase freeze prescriptionOverrides; history prefill never borrows a result whose metric a phase override prescribed, so a deload does not seed the next ordinary week.',
          'categorical':
              'Slots may declare categories:{<lever>:{values:[2–64 identifiers],default}} (1–16 levers such as grip or hands); values have no implied harder order. Efforts may set settings:{<lever>:value} over the slot defaults. Sessions freeze each set\'s planned settings. session set-settings (session/setId/settings) and store set-settings (database/id/expectedVersion/setId/settings) record which values a completed set actually used; omitted levers count as planned and {} clears the record; skipping drops it. History prefill only borrows results performed with the same settings, summaries show settings/actualSettings, series and records keep performed settings as separate contexts (context filter settings:{lever:value}), and progression holds an exposure with unplanned settings for review (targets and counters unchanged). Ordinal rule levels may also carry settings:{<lever>:value} (every level the same levers; targets optional when settings are present): the current level matches targets and settings, advance/deload proposals report nextLevel, and later store/run starts plan the accepted level\'s settings before history prefill. progression track shows controlledSettings/nextSettings; pure progression ordinal takes currentSettings. Reconciliation receipts adopt targets only, so settings return to the plan after one. A lever may declare tempos:{<value>:{phases:[{id,milliseconds}]}} (exactly one per value; at most one tempo lever per slot, exclusive with timing tempo): each set\'s planned value selects its tempo, so timers and managed execution cue that pattern, session summaries show plannedTempo (and performedTempo when set-settings recorded another value), and ordinal levels or threshold stages that move the lever progress tempo.',
          'presets':
              'Named progression presets: preset publish takes database/preset{id,name?,notes?,ruleType double|threshold|ordinal,rule}/expectedRevision and stores immutable numbered revisions (compare-and-set per id; the rule is validated for its type). preset show takes database/presetId/revision?; preset list returns all revisions. progression propose may take preset:{id,revision} instead of rule/ruleType: the explicit revision supplies the rule, the decision freezes a copy and records preset:{id,revision} as provenance (shown by progression show/accept/decline; archives and backups require that revision to exist with the identical rule). Re-proposing the same rule inline drops the provenance. Later preset revisions never change existing decisions or tracks. A preset prescribes nothing by itself.',
          'bouts':
              'Sequence and repeat nodes may declare bout:true to mark one parent bout (drop set, cluster, rest-pause): at least two effort occurrences, never nested in another bout. Child efforts stay ordinary sets with their own results, roles and progression; store/session summary adds bouts:[{path,sets,status}] and counts.bouts {total,planned,completed,skipped,partial} under policy.boutPolicy bodytmi-bout-count/1, so a report counts the bout once and never as extra sets. Supersets and circuits are plain sequences/repeats with authored rests; drop sets are sequences without rests using role drop. Example examples/structures-practice.json.',
          'setSchemes':
              'A plan node {id,type:variant,slot,lever,branches:{<value>:<activity>}} is an authored structural choice (set scheme such as five triples, six doubles, ten singles) selected by one categorical lever of the slot. Branches cover exactly the lever\'s values, each needs an effort, a variant cannot repeat an enclosing variant\'s lever, AMRAP placements cannot sit inside one, and a branch value is imposed on that slot\'s efforts (an effort cannot contradict it). Sessions freeze variantSelections {variantId:value} and expand only the selected branches; the codec rejects forged selections. Starts choose a progression-controlled lever from the track (ordinal levels with settings), else explicit variants:{<slot>:{<lever>:value}} on session/store/run start, else the lever default; an explicit choice of a progression-controlled lever conflicts. When the structure moves to another branch, a uniform controlled vector broadcasts to the new set count; a non-uniform vector needs reconciliation. activity expand/groups take optional variants:{variantId:value}. Derived workout plans may bind efforts in any branch: graph preview/plan-preview take optional variants:{variantId:value} (default: each lever default), previews record variantSelections and list only the selected branch, store/run starts resolve the session\'s own selection, and bindings into other branches stay inactive (validated at publication). Threshold rules may add stages:{lever,order:[{value,failureLimit,advancementLimit}]} (2–64 distinct lever values, limits in the performance metric\'s dimension, replacing the rule limits for that stage): every working set must plan the same stage value; when failed exposures reach deloadAfter the proposal outcome is stage (next stage, every numeric setting held, failures reset), and at the last stage the configured deload applies (outcome deload) or, without deloadMetrics, outcome stage; both restart at the first stage. Proposals report nextStage; accepted decisions control the lever, so later starts plan that stage; declining a stage holds it and keeps previousFailures+1. Pure progression evaluate takes stage. Staged rules cannot back shared lever links. Failure-driven stages may add cycleRestart:{basis:cycleStart|firstStageExit,increments:{<increment metric>:quantity}}: exhausting the last stage restarts at the first stage at the track\'s cycle reference plus the increments (GZCLP T2: back to 10x3, heavier than last cycle), replacing the deload/restart action (a retest policy still takes precedence). The reference is explicit track state carried through decisions (previousReference), nextState.reference and reconciliations: cycleStart records the values a cycle started at, firstStageExit those at which the first stage was last left; before any reference is known the current values stand in. Pure progression evaluate takes state.reference. stages.advanceOn:success makes waves: advancement moves to the next stage (outcome stage) and the wrap from the last stage to the first applies the rule increments (outcome advance); failures count and deload without moving. Each stage may declare offsets:{<increment metric>:quantity} (nonnegative, the same metrics on every stage) added to the base, so moving between stages shifts values by the offset difference; a shift below zero is blocked. A declined success-mode stage move counts as a success. Example examples/wave-practice.json and wave-propose.json.',
          'unilateralSides':
              'Effort activities may declare side:left|right; absent means not side-specific. Log each side as its own effort occurrence, e.g. a repeat of a sequence of left and right efforts. History prefill only borrows a past result from the same side; summaries show each set side; store/history series and records keep left and right in separate contexts, and the series context filter accepts side. Progression still treats every working set of the slot as one vector. The side does not change load conventions; declare repCounting/sides there for interpretation.',
          'branchedLevels':
              'Ordinal rules may declare successors:{levelId:[levelId,...]}, an acyclic graph of declared harder transitions. With it only declared edges authorize advancement and sibling branches stay incomparable: one successor proposes advance; several propose choice (targets held, candidates listed) and progression accept must name selectedLevel among them; none is blocked. A branched deloadLevel must be a declared ancestor of the current level. Without successors the authored array order applies.',
          'substitution':
              'Temporary substitution (policy bodytmi-substitution/1): store substitute takes database/id/expectedVersion/slotId/scope (occurrence with setId, or remaining)/composition{exercise,implementation,equipment?,setupNote?}/targets?{metric:{source:keep|history|explicit,value?}}; session substitute takes session plus optional history. Unlisted metrics use history (latest finished result for the same template, slot, role, ordinal and replacement); otherwise a target stays unresolved with a reason and completing the set needs an explicit actual. The template never changes; substitutes keep their own series context (substituted:true), never prefill the original slot, are excluded from derived-graph history, and are not proposed for the original progression track. store/session revert-substitution restores planned sets exactly.',
          'emom':
              'Author an EMOM as a finite repeat of window nodes (e.g. repeat count 12 of a 60 s window containing one effort). checkpoint start takes database/id/sessionId and creates the scoped clock at the first occurrence of an active session (identical retry returns it); then checkpoint reserve, run or action resume/advance/pause with owner samples. Overrun policy bodytmi-window-overrun/1:stop-partial (shown in checkpoint status): boundaries stay on the authored grid; finishing early uses complete-current and the rest of the window is recovery until the boundary and advance-boundary; unfinished work at a boundary blocks advancing until review-expired records an explicit (possibly partial) result or skip-expired confirms a skip, and the next window starts at that same boundary. No clock transition records a result.',
          'amrapBlocks':
              'A plan node {id,type:amrap,amrapId} places a declared block at one point of the finite plan (at most once per block, never inside a repeat or window): it is one traversal occurrence with no sets; execution show reports kind amrap with the block checkpoint status, execution time/complete/skip reject it, and execution advance requires that session block checkpoint to be finished (stop is an explicit skip), recording checkpointId in the receipt. With a traversal, start-block waits until the cursor reaches the placement; group skips may pass it. Unplaced blocks keep running alongside the plan. Scoped window clocks reject plans with placements. A workout definition may declare amraps: 1-16 authored deadline-bounded AMRAP blocks, each {id,durationMilliseconds,maxRounds,maxOccurrences,roundDefinition} like a repeat loop, pinned in the immutable revision; publication checks each is startable. repeat-checkpoint start-block takes database/id/sessionId/amrapId and creates the block ledger from the active session pinned revision (identical retry returns it; one checkpoint per session block). Run, review, correct and finish it with the existing repeat-checkpoint reserve/run/action commands; skipping a block is an explicit confirmed stop action. A session cannot finish until every authored block has a finished checkpoint. The clock never records rounds or reps: only explicit reviews do. repeat-checkpoint series/rounds report amrapId.',
          'windowStatus':
              'activity window-repeat-page previews one paged virtual round using an explicit deadline and safety limits. activity window-repeat-cursor provides caller-owned structural steps and explicit logical clock samples; it does not save or certify results. activity window-repeat-execution adds explicit effort reviews, including while running with an owner clock sample, version-checked result corrections and outcome revisions, explicit boundary batch reviews and round summaries to a caller-owned cursor; it does not persist training sessions. activity window-status takes definition/occurrence/elapsedMilliseconds/windowStarts. It calculates nested authored window deadlines from explicit shared logical milliseconds. activity window-crossing compares two logical samples and identifies the earliest crossed window boundary and its occurrence bounds, including tied deadlines. activity window-transition calculates entered and exited scopes and carries their logical starts to an explicitly selected later occurrence. activity window-clock operates on an explicit caller-owned clock snapshot with start/resume/advance/pause/recover/move actions. Recovery freezes the last sample or accepts explicit adjustmentMilliseconds; samples and adjustments stop at the first deadline. Clock snapshots retain the current occurrence start and boundary paths and unapplied elapsed time; no results are inferred. session window-clock and store window-clock bind caller-owned clock snapshots to a session and require explicit completed or skipped efforts before movement. session window-review and store window-review explicitly complete or skip the current effort and move the caller-owned clock together using session and clock versions; stored review persists the session but not the clock. repeat-checkpoint save/show/list/delete manage inert repeat snapshots; repeat-checkpoint reserve/release explicitly share the profile timing slot; repeat-checkpoint run uses a foreground monotonic clock with optional bounded duration and streamed boundary events, pauses on Ctrl-C, and needs recovery after unexpected interruption; repeat-checkpoint action supports reserved owner-sampled clock epochs, recovery, reviews, corrections, and explicit elapsed samples with checkpoint and execution versions; A repeat checkpoint can name an active session on creation; its session cannot finish until the repeat finishes, and repeat results stay in its own ledger. checkpoint save/show/list/delete manage session-bound snapshots. session rounds and store rounds report explicit completed and partial iterations of a selected finite repeat, without inferring work from time. checkpoint status derives current occurrence, window deadlines, pending boundary reviews and whether recovery is required before a new owner; it does not change state. checkpoint reserve/release explicitly control the profile timing slot; checkpoint action persists owner-supplied clock samples, and checkpoint review atomically saves explicit results and the moved clock. Release and deletion require confirmation; running clocks require recovery after interruption. Window effort reviews may include explicit nonempty observations, including an interrupted termination reason; no interruption is inferred. checkpoint complete-current explicitly records the current effort while leaving the clock on its window, so the remaining time can be used for recovery. checkpoint review-expired-batch records explicitly reviewed efforts and confirmed skips together at a boundary. checkpoint review-expired explicitly completes the current effort and skips remaining planned work atomically at a boundary. checkpoint skip-expired explicitly skips remaining planned work in the expired window and moves its checkpoint atomically, requiring confirm:true. checkpoint advance-boundary moves past expired windows only when all crossed efforts were reviewed. checkpoint advance-rest acknowledges a reached timed rest or confirmed manual rest and prepares the next occurrence paused. checkpoint run uses a foreground monotonic clock until a boundary or optional runForMilliseconds; advanceReviewed:true optionally moves past fully reviewed boundaries and pauses at the next occurrence; stopAtRest:true pauses at the current authored timed-rest target, unless a window boundary comes first; advanceRest:true optionally moves to the next paused occurrence after that target; stream:true emits NDJSON start and boundary events. Ctrl-C pauses; unexpected interruption requires checkpoint action recover. Automatic traversal remains pending.',
          'tempoSample':
              'tempo sample takes tempo/previousElapsedMilliseconds/elapsedMilliseconds and optional includeInitial. It returns the current phase and at most the newest crossed cue from explicit effort-time samples; it does not own a clock, deliver audio or count reps.',
          'unplannedTiming':
              'timer start and execution time/run can time a set without a prescribed duration metric using an explicit plan with unplannedDuration:true and an explicit unused duration metric ID. Specify either effortMilliseconds or openEnded:true; end open-ended effort explicitly. Tempo is optional. Confirming records elapsed duration and requires explicit remaining actuals or acceptSuggested. A slot may instead publish timing with metric and openEnded:true plus optional preparation and tempo; omitted clock plans use the pinned guidance. The workout prescription is unchanged.',
          'roleProgressionPreview':
              'session progression-preview takes session/slotId/rule and optional role, ruleType and state; store progression-preview takes database/id instead of session and optionally useTrack:true to load current run/role lineage instead of state. Active sessions can be previewed but must be finalized before creating durable decisions. Role defaults to work; ruleType defaults to double. Preview is read-only and does not apply targets or create progression decisions.',
          'progressionTrack':
              'progression track takes database/templateId/revision/slotId/asOf and optional runId/role. It reports the latest resolved decision eligible at the cutoff, with controlled targets and current source-change status; omitted runId selects ad hoc sessions. It does not check prescription compatibility or apply progression.',
        }),
      );
      return;
    }
    if (arguments.length == 1 && arguments.single == '--version') {
      stdout.writeln(jsonEncode({'schemaVersion': 1, 'version': '0.1.0'}));
      return;
    }
    if (arguments.length != 2 && arguments.length != 4) {
      throw const BodyTmiException(
        'usage',
        'Expected <group> <action> [--input FILE|-].',
      );
    }
    final command = arguments.take(2).join(' ');
    if ((!commandNames.contains(command) &&
            !storedCommandNames.contains(command)) ||
        (arguments.length == 4 && arguments[2] != '--input')) {
      throw const BodyTmiException(
        'usage',
        'Unknown command/option. Use --help.',
      );
    }
    const maxBytes = 8 * 1024 * 1024;
    final inputPath = arguments.length == 4 ? arguments[3] : '-';
    final stream = inputPath == '-' ? stdin : File(inputPath).openRead();
    final bytes = BytesBuilder(copy: false);
    await for (final chunk in stream) {
      if (bytes.length + chunk.length > maxBytes)
        invalid('Request exceeds the 8 MiB resource limit.');
      bytes.add(chunk);
    }
    final request = jsonObject(
      jsonDecode(utf8.decode(bytes.takeBytes())),
      'request',
    );
    final response = storedCommandNames.contains(command)
        ? await executeStored(command, request)
        : const Commands().execute(command, request);
    stdout.writeln(jsonEncode(response));
  } on BodyTmiException catch (error) {
    _error(error.code, error.message);
    exitCode = switch (error.code) {
      'not_found' => 3,
      'conflict' || 'in_use' => 5,
      'storage' => 4,
      _ => 2,
    };
  } on FormatException catch (error) {
    _error('validation', 'Invalid JSON/text: ${error.message}');
    exitCode = 2;
  } on SqliteException catch (error) {
    _error('storage', error.message);
    exitCode = 4;
  } on FileSystemException catch (error) {
    _error('io', error.message);
    exitCode = 4;
  } catch (error, stack) {
    _error('internal', '$error');
    stderr.writeln(stack);
    exitCode = 70;
  }
}

void _error(String code, String message) => stderr.writeln(
  jsonEncode({
    'schemaVersion': 1,
    'error': {'code': code, 'message': message},
  }),
);
